import React, { useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { format, parseISO } from 'date-fns';
import {
  Button,
  Checkbox,
  Input,
  SearchInput,
  Select,
} from '@linm-soft-org/linm-web-common-components';
import { createMaterialSearchConfig } from '../../../components/search';
import type { MaterialDto } from '../../../services/master/models';
import {
  listSalesPlans,
  type SalesPlanFilterQuery,
  type SalesPlanListItem,
} from '../../../services/salesPlans/endpoint';
import df from '../../../styles/documentForm.module.css';

type SearchState = {
  ngayCt1: string;
  ngayCt2: string;
  soCt1: string;
  soCt2: string;
  maKh: string;
  maKho: string;
  maVt: string;
  dienGiai: string;
  maGd: string;
  maPost: string;
  nhVt1: string;
  nhVt2: string;
  nhVt3: string;
  nhVt4: string;
  nhVt5: string;
  tien1: string;
  tien2: string;
  maPhi: string;
  maVv: string;
  maHd: string;
  maSp: string;
  maKu: string;
  maTtln: string;
  maTtcp: string;
  maBp: string;
  maHs: string;
  maCd: string;
  maTd1: string;
  maTd2: string;
  maTd3: string;
  maTd4: string;
  maTd5: string;
  locNsd: boolean;
};

const EMPTY_SEARCH: SearchState = {
  ngayCt1: '',
  ngayCt2: '',
  soCt1: '',
  soCt2: '',
  maKh: '',
  maKho: '',
  maVt: '',
  dienGiai: '',
  maGd: '',
  maPost: '9',
  nhVt1: '',
  nhVt2: '',
  nhVt3: '',
  nhVt4: '',
  nhVt5: '',
  tien1: '',
  tien2: '',
  maPhi: '',
  maVv: '',
  maHd: '',
  maSp: '',
  maKu: '',
  maTtln: '',
  maTtcp: '',
  maBp: '',
  maHs: '',
  maCd: '',
  maTd1: '',
  maTd2: '',
  maTd3: '',
  maTd4: '',
  maTd5: '',
  locNsd: false,
};

const NH_VT = ['nhVt1', 'nhVt2', 'nhVt3', 'nhVt4', 'nhVt5'] as const;
const MA_TD = ['maTd1', 'maTd2', 'maTd3', 'maTd4', 'maTd5'] as const;
const EXTRA_CODES: { key: keyof SearchState; label: string }[] = [
  { key: 'maPhi', label: 'Khoản mục' },
  { key: 'maVv', label: 'Vụ việc' },
  { key: 'maHd', label: 'Hợp đồng' },
  { key: 'maSp', label: 'Sản phẩm' },
  { key: 'maKu', label: 'Khế ước' },
  { key: 'maTtln', label: 'Trung tâm lợi nhuận' },
  { key: 'maTtcp', label: 'Trung tâm chi phí' },
  { key: 'maBp', label: 'Bộ phận' },
  { key: 'maHs', label: 'Nhân sự' },
  { key: 'maCd', label: 'Công đoạn' },
];

function showDate(value: string | null | undefined): string {
  if (!value) return '';
  const parsed = parseISO(value);
  if (Number.isNaN(parsed.getTime())) return value;
  return format(parsed, 'dd/MM/yyyy');
}

function toQuery(state: SearchState): SalesPlanFilterQuery {
  const query: SalesPlanFilterQuery = { maPost: state.maPost === '3' ? '3' : '9' };
  const textKeys: (keyof SearchState)[] = [
    'ngayCt1', 'ngayCt2', 'soCt1', 'soCt2', 'maKh', 'maKho', 'maVt', 'dienGiai', 'maGd',
    'nhVt1', 'nhVt2', 'nhVt3', 'nhVt4', 'nhVt5', 'tien1', 'tien2',
    'maPhi', 'maVv', 'maHd', 'maSp', 'maKu', 'maTtln', 'maTtcp', 'maBp', 'maHs', 'maCd',
    'maTd1', 'maTd2', 'maTd3', 'maTd4', 'maTd5',
  ];
  textKeys.forEach(key => {
    const value = state[key];
    if (typeof value === 'string' && value.trim()) {
      (query as Record<string, string>)[key] = value.trim();
    }
  });
  if (state.locNsd) query.locNsd = true;
  return query;
}

const Kh4ListPage: React.FC = () => {
  const navigate = useNavigate();
  const materialSearch = useMemo(() => createMaterialSearchConfig(), []);
  const [search, setSearch] = useState<SearchState>(EMPTY_SEARCH);
  const [items, setItems] = useState<SalesPlanListItem[]>([]);
  const [filtering, setFiltering] = useState(false);
  const [selectedSttRec, setSelectedSttRec] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const patch = (next: Partial<SearchState>) => setSearch(prev => ({ ...prev, ...next }));

  const applyRows = (rows: SalesPlanListItem[]) => {
    setItems(rows);
    setSelectedSttRec(prev => (rows.some(row => row.sttRec === prev) ? prev : ''));
  };

  const loadTop = async () => {
    setError('');
    setLoading(true);
    try {
      applyRows(await listSalesPlans({ loadTop: 5 }));
    } catch (err) {
      setItems([]);
      setSelectedSttRec('');
      setError(err instanceof Error ? err.message : 'Không tải được danh sách kế hoạch bán hàng');
    } finally {
      setLoading(false);
    }
  };

  const runSearch = async (state: SearchState) => {
    setFiltering(true);
    setError('');
    setLoading(true);
    try {
      applyRows(await listSalesPlans(toQuery(state)));
    } catch (err) {
      setItems([]);
      setSelectedSttRec('');
      setError(err instanceof Error ? err.message : 'Không tải được danh sách kế hoạch bán hàng');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadTop();
  }, []);

  const onSearch = () => {
    void runSearch(search);
  };

  const onRefresh = () => {
    if (!filtering) {
      void loadTop();
      return;
    }
    void runSearch(search);
  };

  const onEnter = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      onSearch();
    }
  };

  const noSelection = !selectedSttRec;
  const emptyText = filtering
    ? 'Không tìm thấy kế hoạch bán hàng'
    : 'Không có kế hoạch bán hàng';

  return (
    <div className={df.page} data-testid="ct-kh4-list">
      <h1 data-testid="ct-kh4-title">Kế hoạch bán hàng</h1>
      <div>
        <Button variant="secondary" data-testid="ct-kh4-toolbar-refresh-btn" onClick={onRefresh} loading={loading}>
          Làm mới
        </Button>
        <Button variant="primary" data-testid="ct-kh4-toolbar-add-btn" onClick={() => navigate('/bh/kh4/them')}>
          Thêm
        </Button>
        <Button
          variant="secondary"
          data-testid="ct-kh4-toolbar-edit-btn"
          disabled={noSelection}
          onClick={() => navigate(`/bh/kh4/${encodeURIComponent(selectedSttRec)}`)}
        >
          Sửa
        </Button>
        <Button
          variant="secondary"
          data-testid="ct-kh4-toolbar-view-btn"
          disabled={noSelection}
          onClick={() => navigate(`/bh/kh4/${encodeURIComponent(selectedSttRec)}?mode=view`)}
        >
          Xem
        </Button>
        <Button
          variant="secondary"
          data-testid="ct-kh4-toolbar-copy-btn"
          disabled={noSelection}
          onClick={() => navigate(`/bh/kh4/them?copyFrom=${encodeURIComponent(selectedSttRec)}`)}
        >
          Sao chép
        </Button>
      </div>

      <section className={df.section} data-testid="ct-kh4-search">
        <h2 className={df.sectionTitle}>Tìm kiếm</h2>
        <div className={df.row4}>
          <div className={df.field}>
            <label className={df.label}>Ngày chứng từ từ</label>
            <Input type="date" data-testid="ct-kh4-search-ngayCt1" value={search.ngayCt1} onKeyDown={onEnter} onChange={e => patch({ ngayCt1: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Ngày chứng từ đến</label>
            <Input type="date" data-testid="ct-kh4-search-ngayCt2" value={search.ngayCt2} onKeyDown={onEnter} onChange={e => patch({ ngayCt2: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Số chứng từ từ</label>
            <Input data-testid="ct-kh4-search-soCt1" value={search.soCt1} onKeyDown={onEnter} onChange={e => patch({ soCt1: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Số chứng từ đến</label>
            <Input data-testid="ct-kh4-search-soCt2" value={search.soCt2} onKeyDown={onEnter} onChange={e => patch({ soCt2: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Đối tượng</label>
            <Input data-testid="ct-kh4-search-maKh" value={search.maKh} onKeyDown={onEnter} onChange={e => patch({ maKh: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Kho</label>
            <Input data-testid="ct-kh4-search-maKho" value={search.maKho} onKeyDown={onEnter} onChange={e => patch({ maKho: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Vật tư</label>
            <SearchInput
              config={materialSearch}
              value={search.maVt}
              primaryDisplay={search.maVt}
              onChange={(item: MaterialDto) => patch({ maVt: item.code })}
              onClear={() => patch({ maVt: '' })}
              showLabel={false}
              data-testid="ct-kh4-search-maVt"
            />
          </div>
          <div className={`${df.field} ${df.spanCol2}`}>
            <label className={df.label}>Diễn giải</label>
            <Input data-testid="ct-kh4-search-dienGiai" value={search.dienGiai} onKeyDown={onEnter} onChange={e => patch({ dienGiai: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Loại giao dịch</label>
            <Select
              data-testid="ct-kh4-search-maGd"
              value={search.maGd}
              onChange={e => patch({ maGd: e.target.value })}
              options={[
                { value: '', label: 'Tất cả' },
                { value: '2', label: 'Lập kế hoạch bán hàng' },
              ]}
            />
          </div>
        </div>
        <Button variant="primary" data-testid="ct-kh4-search-btn" onClick={onSearch} loading={loading}>
          Tìm
        </Button>
      </section>

      <section className={df.section} data-testid="ct-kh4-search-extra">
        <h2 className={df.sectionTitle}>Điều kiện thêm</h2>
        <div className={df.row4}>
          <div className={df.field}>
            <label className={df.label}>Trạng thái</label>
            <Select
              data-testid="ct-kh4-search-maPost"
              value={search.maPost}
              onChange={e => patch({ maPost: e.target.value })}
              options={[
                { value: '3', label: 'Lập kế hoạch' },
                { value: '9', label: 'Kế hoạch đã phê duyệt' },
              ]}
            />
          </div>
          {NH_VT.map((key, index) => (
            <div className={df.field} key={key}>
              <label className={df.label}>{`Nhóm vật tư ${index + 1}`}</label>
              <Input
                data-testid={`ct-kh4-search-${key}`}
                value={search[key]}
                onKeyDown={onEnter}
                onChange={e => patch({ [key]: e.target.value })}
              />
            </div>
          ))}
          <div className={df.field}>
            <label className={df.label}>Tiền NT từ</label>
            <Input inputMode="decimal" data-testid="ct-kh4-search-tien1" value={search.tien1} onKeyDown={onEnter} onChange={e => patch({ tien1: e.target.value })} />
          </div>
          <div className={df.field}>
            <label className={df.label}>Tiền NT đến</label>
            <Input inputMode="decimal" data-testid="ct-kh4-search-tien2" value={search.tien2} onKeyDown={onEnter} onChange={e => patch({ tien2: e.target.value })} />
          </div>
          {EXTRA_CODES.map(field => (
            <div className={df.field} key={field.key}>
              <label className={df.label}>{field.label}</label>
              <Input
                data-testid={`ct-kh4-search-${field.key}`}
                value={String(search[field.key] ?? '')}
                onKeyDown={onEnter}
                onChange={e => patch({ [field.key]: e.target.value })}
              />
            </div>
          ))}
          {MA_TD.map((key, index) => (
            <div className={df.field} key={key}>
              <label className={df.label}>{`Mã tự do ${index + 1}`}</label>
              <Input
                data-testid={`ct-kh4-search-${key}`}
                value={search[key]}
                onKeyDown={onEnter}
                onChange={e => patch({ [key]: e.target.value })}
              />
            </div>
          ))}
          <div className={df.field}>
            <Checkbox
              label="Chỉ chứng từ của tôi"
              data-testid="ct-kh4-search-locNsd"
              checked={search.locNsd}
              onChange={e => patch({ locNsd: e.target.checked })}
            />
          </div>
        </div>
      </section>

      {error ? <div className={df.errorBanner}>{error}</div> : null}
      <div className={df.tableWrapper}>
        <table className={df.linesTable} data-testid="ct-kh4-grid">
          <thead>
            <tr>
              <th>Số chứng từ</th>
              <th>Kế hoạch từ ngày</th>
              <th>Kế hoạch đến ngày</th>
            </tr>
          </thead>
          <tbody>
            {items.map(row => {
              const selected = row.sttRec === selectedSttRec;
              return (
                <tr
                  key={row.sttRec}
                  aria-selected={selected}
                  onClick={() => setSelectedSttRec(row.sttRec)}
                  style={selected ? { background: 'var(--ds-color-primary-bg, rgba(13, 110, 253, 0.08))' } : undefined}
                >
                  <td>{row.soCt}</td>
                  <td>{showDate(row.ngayKh1)}</td>
                  <td>{showDate(row.ngayKh2)}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      {items.length === 0 ? <div>{emptyText}</div> : null}
    </div>
  );
};

export default Kh4ListPage;
